/**
 * 检索管线:query → BM25 ∥ 向量 → 融合 → rerank → 阈值 → 预算。
 *
 * 全部配置由调用方传入,不直接读 settings —— 调试台要能用一组临时参数试跑而不影响线上召回。
 *
 * 失败一律降级,绝不向上抛:
 *  - embed 失败 → 只剩 BM25
 *  - rerank 失败 → 用融合序,并切到融合阈值(两种分数尺度不可比,共用阈值必然要么全放要么全过)
 *  - 全失败 → 空结果,由调用方清空注入槽
 */

import { bm25Score, type Bm25Params } from '../engine/bm25.ts';
import { getChunksByOrdinal, getPostingRows, loadVectorMatrix } from '../engine/db.ts';
import { getMeta } from '../engine/db.ts';
import { scanInt8Matrix } from '../engine/quantize.ts';
import { tokenize } from '../engine/tokenize.ts';
import { embedQuery } from './embed.ts';
import { rrf, weightedNormalized, type Channel, type FusedHit, type Hit } from './fuse.ts';
import { describeError, type EndpointConfig } from './http.ts';
import { rerankDocuments } from './rerank.ts';

export interface RetrievalParams {
  bm25TopN: number;
  vectorTopN: number;
  fuseTopN: number;
  rerankTopK: number;
  rrfK: number;
  fusionMode: 'rrf' | 'weighted';
  weights: { bm25: number; vector: number };
  bm25: Bm25Params;
  rerankThreshold: number;
  fuseThreshold: number;
  charBudget: number;
}

export interface KbRef {
  id: string;
  name: string;
}

export interface PipelineDeps {
  params: RetrievalParams;
  embedCfg: EndpointConfig;
  rerankCfg: EndpointConfig;
  kbs: KbRef[];
  signal?: AbortSignal;
  /** 保留四栏的标题与摘要;调试台和需回看的真实召回开启,否则只加载融合候选正文。 */
  debug?: boolean;
}

export interface RetrievalHit {
  kbId: string;
  kbName: string;
  ordinal: number;
  title: string;
  document: string;
  score: number;
}

/** 调试台用的单阶段命中。debug 关闭时 title/preview 为空串。 */
export interface StageHit {
  ref: number;
  kbId: string;
  kbName: string;
  ordinal: number;
  title: string;
  preview: string;
  score: number;
  ranks?: Record<string, number>;
}

export interface DebugSnapshot {
  query: string;
  terms: string[];
  stages: { bm25: StageHit[]; vector: StageHit[]; fused: StageHit[]; reranked: StageHit[] };
  timings: Record<string, number>;
  /** 降级与跳过的原因,直接显示给用户 */
  notes: string[];
  degraded: { embed: boolean; rerank: boolean };
}

export interface RetrievalOutcome {
  hits: RetrievalHit[];
  debug: DebugSnapshot;
}

/** 跨库统一编号:融合算法只认数字下标,这里把 (kbId, ordinal) 折叠成本次查询内的序号。 */
class RefTable {
  private readonly byKey = new Map<string, number>();
  readonly refs: Array<{ kbId: string; kbName: string; ordinal: number }> = [];

  idOf(kb: KbRef, ordinal: number): number {
    const key = `${kb.id}�${ordinal}`;
    const hit = this.byKey.get(key);
    if (hit !== undefined) return hit;
    const id = this.refs.length;
    this.refs.push({ kbId: kb.id, kbName: kb.name, ordinal });
    this.byKey.set(key, id);
    return id;
  }
}

const now = (): number => (typeof performance !== 'undefined' ? performance.now() : Date.now());

/** 单库 BM25。倒排表只取 query 命中的那几十个 term。 */
async function bm25ForKb(
  kb: KbRef,
  terms: string[],
  params: RetrievalParams,
  table: RefTable,
): Promise<Hit[]> {
  const meta = await getMeta(kb.id);
  if (!meta || meta.N === 0) return [];
  const rows = await getPostingRows(kb.id, terms);
  if (!rows.length) return [];

  return bm25Score(
    rows,
    { N: meta.N, avgdl: meta.avgdl, docLens: meta.docLens },
    params.bm25TopN,
    params.bm25,
  ).map(h => ({ o: table.idOf(kb, h.o), score: h.score }));
}

/** 单库向量全量扫描。 */
async function vectorForKb(
  kb: KbRef,
  queryVec: Float32Array,
  params: RetrievalParams,
  table: RefTable,
  model: string,
  onSkipped: (note: string) => void,
): Promise<Hit[]> {
  const meta = await getMeta(kb.id);
  // 同维度不代表同一向量空间,更换模型后必须等重导完成才能比较。
  if (meta && meta.embedModel !== model) {
    onSkipped(`「${kb.name}」向量索引模型与当前配置不同,已跳过向量召回,请重导该库`);
    return [];
  }
  const mx = await loadVectorMatrix(kb.id);
  if (!mx || mx.dim !== queryVec.length) return [];

  const scores = scanInt8Matrix(queryVec, mx.matrix, mx.scales, mx.dim, mx.count);
  const idx = Array.from(scores.keys());
  idx.sort((a, b) => scores[b]! - scores[a]!);

  return idx.slice(0, params.vectorTopN).map(i => ({
    o: table.idOf(kb, mx.ordinals[i]!),
    score: scores[i]!,
  }));
}

/** 按库分组批量回捞正文,避免逐条读 IndexedDB。 */
async function loadDocuments(
  table: RefTable,
  refIds: number[],
): Promise<Map<number, { title: string; document: string }>> {
  const byKb = new Map<string, number[]>();
  for (const id of refIds) {
    const ref = table.refs[id];
    if (!ref) continue;
    const list = byKb.get(ref.kbId);
    if (list) list.push(id);
    else byKb.set(ref.kbId, [id]);
  }

  const out = new Map<number, { title: string; document: string }>();
  await Promise.all(
    [...byKb.entries()].map(async ([kbId, ids]) => {
      const ordinals = ids.map(id => table.refs[id]!.ordinal);
      const chunks = await getChunksByOrdinal(kbId, ordinals);
      const byOrdinal = new Map(chunks.map(c => [c.ordinal, c]));
      for (const id of ids) {
        const c = byOrdinal.get(table.refs[id]!.ordinal);
        if (c) out.set(id, { title: c.title, document: c.document });
      }
    }),
  );
  return out;
}

function toStageHits(
  table: RefTable,
  hits: Array<Hit | FusedHit>,
  docs: Map<number, { title: string; document: string }> | null,
): StageHit[] {
  return hits.map(h => {
    const ref = table.refs[h.o]!;
    const doc = docs?.get(h.o);
    const base: StageHit = {
      ref: h.o,
      kbId: ref.kbId,
      kbName: ref.kbName,
      ordinal: ref.ordinal,
      title: doc?.title ?? '',
      preview: doc ? doc.document.slice(0, 120) : '',
      score: h.score,
    };
    if ('ranks' in h) base.ranks = h.ranks;
    return base;
  });
}

export async function retrieve(query: string, deps: PipelineDeps): Promise<RetrievalOutcome> {
  const { params, kbs, signal, debug = false } = deps;
  const timings: Record<string, number> = {};
  const notes: string[] = [];
  const degraded = { embed: false, rerank: false };
  const table = new RefTable();
  const terms = tokenize(query);

  const empty = (): RetrievalOutcome => ({
    hits: [],
    debug: {
      query,
      terms,
      stages: { bm25: [], vector: [], fused: [], reranked: [] },
      timings,
      notes,
      degraded,
    },
  });

  if (!kbs.length) {
    notes.push('没有已启用的知识库');
    return empty();
  }
  if (!query.trim()) {
    notes.push('查询为空');
    return empty();
  }

  /* 1. 两路并行召回。任一路失败不影响另一路。 */
  const t0 = now();

  const bm25Task = (async (): Promise<Hit[]> => {
    if (!terms.length) {
      notes.push('查询分词后为空,BM25 跳过');
      return [];
    }
    const perKb = await Promise.all(kbs.map(kb => bm25ForKb(kb, terms, params, table)));
    return perKb.flat().sort((a, b) => b.score - a.score).slice(0, params.bm25TopN);
  })();

  const vectorTask = (async (): Promise<Hit[]> => {
    try {
      const qv = await embedQuery(query, deps.embedCfg, signal);
      const perKb = await Promise.all(kbs.map(kb => vectorForKb(
        kb, qv, params, table, deps.embedCfg.model, note => {
          degraded.embed = true;
          notes.push(note);
        },
      )));
      return perKb.flat().sort((a, b) => b.score - a.score).slice(0, params.vectorTopN);
    } catch (e) {
      degraded.embed = true;
      notes.push(`向量召回降级(只剩 BM25):${describeError(e)}`);
      return [];
    }
  })();

  const [bm25Hits, vectorHits] = await Promise.all([bm25Task, vectorTask]);
  timings.recall = now() - t0;

  if (!bm25Hits.length && !vectorHits.length) {
    notes.push('两路召回均无命中');
    return empty();
  }

  /* 2. 融合 */
  const t1 = now();
  const channels: Channel[] = [
    { name: 'bm25', hits: bm25Hits },
    { name: 'vector', hits: vectorHits },
  ];
  const fused =
    params.fusionMode === 'weighted'
      ? weightedNormalized(channels, params.weights, params.fuseTopN)
      : rrf(channels, params.fuseTopN, params.rrfK);
  timings.fuse = now() - t1;

  /* 3. 回捞正文 —— rerank 与注入都需要,顺带供调试台展示 */
  const docsFor = debug
    ? [...new Set([...bm25Hits, ...vectorHits, ...fused].map(h => h.o))]
    : fused.map(h => h.o);
  const t2 = now();
  const docs = await loadDocuments(table, docsFor);
  timings.load = now() - t2;

  const candidates = fused.filter(h => docs.has(h.o));

  /* 4. rerank。失败则降级为融合序,阈值同步切换。 */
  const t3 = now();
  let ranked: Array<{ o: number; score: number }> = candidates;
  let threshold = params.fuseThreshold;

  if (candidates.length) {
    try {
      const order = await rerankDocuments(
        query,
        candidates.map(h => docs.get(h.o)!.document),
        deps.rerankCfg,
        signal,
      );
      ranked = order
        .filter(r => candidates[r.index])
        .map(r => ({ o: candidates[r.index]!.o, score: r.score }));
      threshold = params.rerankThreshold;
    } catch (e) {
      degraded.rerank = true;
      notes.push(`Rerank 降级(改用融合序与融合阈值):${describeError(e)}`);
    }
  }
  timings.rerank = now() - t3;

  /* 5. 阈值 → topK → 字符预算 */
  const passed = ranked.filter(h => h.score >= threshold).slice(0, params.rerankTopK);
  if (ranked.length && !passed.length) {
    notes.push(`全部候选未过阈值 ${threshold}`);
  }

  const hits: RetrievalHit[] = [];
  let used = 0;
  for (const h of passed) {
    const doc = docs.get(h.o)!;
    const ref = table.refs[h.o]!;
    // 预算不够就停,不截断单条 —— 半条词条注入进去比不注入更容易误导模型
    if (used + doc.document.length > params.charBudget && hits.length > 0) break;
    hits.push({
      kbId: ref.kbId,
      kbName: ref.kbName,
      ordinal: ref.ordinal,
      title: doc.title,
      document: doc.document,
      score: h.score,
    });
    used += doc.document.length;
  }

  if (passed.length > hits.length) {
    notes.push(`字符预算 ${params.charBudget} 已满,截到 ${hits.length} 条`);
  }

  return {
    hits,
    debug: {
      query,
      terms,
      stages: {
        bm25: toStageHits(table, bm25Hits, debug ? docs : null),
        vector: toStageHits(table, vectorHits, debug ? docs : null),
        fused: toStageHits(table, fused, debug ? docs : null),
        reranked: toStageHits(table, passed, debug ? docs : null),
      },
      timings,
      notes,
      degraded,
    },
  };
}
